class ContactSection extends StatefulWidget { const ContactSection({super.key,required this.controller,this.mapsApiKey}); final ContactController controller; final String? mapsApiKey; @override State<ContactSection> createState()=>_ContactSectionState(); }
class _ContactSectionState extends State<ContactSection> { final _form=GlobalKey<FormState>(); final _name=TextEditingController(),_email=TextEditingController(),_phone=TextEditingController(),_message=TextEditingController(); bool _sending=false; @override void dispose(){_name.dispose();_email.dispose();_phone.dispose();_message.dispose();super.dispose();}
@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const SectionHeading(eyebrow:'Get in touch',title:'Let’s talk about what you need',subtitle:'Send an inquiry to the DDCS team.'),const SizedBox(height:18),Card(child:Padding(padding:const EdgeInsets.all(16),child:Form(key:_form,child:Column(children:[TextFormField(controller:_name,decoration:const InputDecoration(labelText:'Full name'),validator:(v)=>(v==null||v.trim().length<2)?'Enter your name':null),const SizedBox(height:12),TextFormField(controller:_email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email address'),validator:(v)=>(v==null||!RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$').hasMatch(v.trim()))?'Enter a valid email':null),const SizedBox(height:12),TextFormField(controller:_phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone (optional)')),const SizedBox(height:12),TextFormField(controller:_message,minLines:3,maxLines:5,decoration:const InputDecoration(labelText:'How can we help?'),validator:(v)=>(v==null||v.trim().length<10)?'Write at least 10 characters':null),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:_sending?null:_submit,icon:_sending?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.send),label:Text(_sending?'Sending…':'Send inquiry')))])))),const SizedBox(height:16),_link(Icons.phone_outlined,'Call the studio','Add your business phone','tel:+910000000000'),_link(Icons.chat_outlined,'WhatsApp','Chat with DDCS','https://wa.me/'),_link(Icons.mail_outline,'Email','Add your business email','mailto:hello@example.com'),const SizedBox(height:16),ClipRRect(borderRadius:BorderRadius.circular(20),child:SizedBox(height:220,child:GoogleMap(initialCameraPosition:const CameraPosition(target:LatLng(26.8467,80.9462),zoom:12),markers:{Marker(markerId: