Future<void> _submit()async{if(!_form.currentState!.validate())return;setState(()=>_sending=true);try{await widget.controller.submit(name:_name.text,email:_email.text,phone:_phone.text,message:_message.text);if(!mounted)return;_form.currentState!.reset();_name.clear();_email.clear();_phone.clear();_message.clear();ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Inquiry submitted successfully.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not submit inquiry: $e')));}finally{if(mounted)setState(()=>_sending=false);}}
